/// <summary>
/// Class for Document transfer
/// </summary>
internal final class NDXRicoReqDocuTransfer
{
    const DataAreaId ric = 'ric';
    const str RICOKI17proAlpha = 'RICOKI17.proAlpha';

    DocuRef     docuRef;
    DocuValue   docuValue;
    DocuType    docuType;

    KCS_KBVRequestID mKCS_KBVRequestID;
    KCS_KBVBuildingProjectID mKCS_KBVBuildingProjectID;
    NDXRicoKalkBVNr mNDX_RicoKalkBVNr;

    Niedax.RICOSchnittstelle_Nx.RICOtblAx2Rk_DMS rICOtblAx2Rk_DMS;

    KCS_KBVParameters lKCS_KBVParameters = KCS_KBVParameters::find();
    Niedax.AzureRelayHelper.AzureRelayParameter azureRelayParameter;

}

Method.Source:
protected void new(DocuRef _docuRef, DocuValue _docuValue = null, int _abruf = 0)
{
    const str RicoDocDepositionError = "@NDX:NDXRicoReqDocuTransferInfo";

    KCS_KBVRequestTable lKCS_KBVRequestTable;
    azureRelayParameter = new Niedax.AzureRelayHelper.AzureRelayParameter();

    str secretValue = KeyVaultCertificateHelper::getManualSecretValue(KeyVaultCertificateTable::findByName(KCS_KBVParameters::find().NDXKeyVaultSecretNameConnectionStringAzureRelayD365FO).RecId);
    azureRelayParameter =  Niedax.AzureRelayHelper.AzureRelayParameter::deserialize(secretValue);


    docuRef = _docuRef;

    if(docuRef != null)
    {
        select firstonly lKCS_KBVRequestTable
            where lKCS_KBVRequestTable.RecId == _docuRef.RefRecId;

        if(!lKCS_KBVRequestTable)
        {
            select firstonly crosscompany lKCS_KBVRequestTable
                where lKCS_KBVRequestTable.RecId == _docuRef.RefRecId;
        }

        // if there is no KCS_KBVRequestTable record then we need to stop here. It does not make any sence to proceed
        if(!lKCS_KBVRequestTable)
        {
            return;
        }

        mKCS_KBVRequestID = lKCS_KBVRequestTable.KCS_KBVRequestID;
        mKCS_KBVBuildingProjectID = KCS_KBVRequestTable::find(mKCS_KBVRequestID).KCS_KBVBuildingProjectID;

        docuType            = docuRef.docuType();
        docuValue           = docuRef.docuValue();
    }

    //Overwrite  docuValue with _docuvalue only if docuValue was not found for valueRecId in docuref
    if(_docuValue != null && docuValue == null)
    {
        docuValue = _docuValue;
    }

    //this.checkRicoBVNr();
    this.init();
    rICOtblAx2Rk_DMS.AbrufNr = _abruf;

}

/// <summary>
/// init RICOtblAx2Rk_DMS object member
/// </summary>
private void init()
{
    str fileExtension = '';
    rICOtblAx2Rk_DMS = new Niedax.RICOSchnittstelle_Nx.RICOtblAx2Rk_DMS(lKCS_KBVParameters.NDXTestEnvironment);
    rICOtblAx2Rk_DMS.KBVRequestID = mKCS_KBVRequestID;
    rICOtblAx2Rk_DMS.BVNr = mNDX_RicoKalkBVNr;

    if(docuref != null)
    {
        fileExtension = docuRef.fileExtension();

        if(docuValue != null)
        {
            fileExtension = docuValue.FileType;
        }

        rICOtblAx2Rk_DMS.Benutzer = docuRef.CreatedBy;
        rICOtblAx2Rk_DMS.Dateiname = guid2StrWithoutBraces(docuRef.DocumentId) + '.' + fileExtension;
        rICOtblAx2Rk_DMS.Betreff = docuRef.Name;
    }
}

/// <summary>
/// init from Rico transfer protocol
/// </summary>
/// <param name = "_NDX_RicoReqDocProt">NDXRicoReqDocProt record</param>
void initByNDX_RicoReqDocProt(NDXRicoReqDocProt _NDX_RicoReqDocProt)
{
    mKCS_KBVBuildingProjectID = _NDX_RicoReqDocProt.KCSKBVBuildingProjectID;
    mKCS_KBVRequestID = _NDX_RicoReqDocProt.KCSKBVRequestID;
    mNDX_RicoKalkBVNr = _NDX_RicoReqDocProt.NDXRicoKalkBVNr;

    this.init();

    //init with protocol values
    rICOtblAx2Rk_DMS.ID = _ndx_RicoReqDocProt.RicoLogID;
    rICOtblAx2Rk_DMS.Benutzer = _ndx_RicoReqDocProt.CreatedBy;
    rICOtblAx2Rk_DMS.Aktion = enum2Symbol(enumNum(NDXRICODMSAction), _NDX_RicoReqDocProt.Action);
    rICOtblAx2Rk_DMS.Dateiname = _ndx_RicoReqDocProt.Filename;
    rICOtblAx2Rk_DMS.Betreff = _ndx_RicoReqDocProt.Name;

    //init doc ref if resending the filecontent again
    this.docuRef = DocuRef::findRecId(_ndx_RicoReqDocProt.DocuRefRecId);

    // If docuvalue is empty
    if(docuRef != null && docuValue == null && _NDX_RicoReqDocProt.Action == NDXRICODMSAction::Anlage)
    {
        docuvalue = DocuValue::find(docuRef.ValueRecId);
    }

}

/// <summary>
/// Insert document to RICO by azure relay
/// </summary>
/// <returns>True or false if record was inserted</returns>
private boolean insertDocument()
{
    boolean ret;
    System.Exception ex;
    System.Net.Http.HttpResponseMessage httpResponseMessage;

    const str Test = 'Test';

    Niedax.AzureServiceBus.Models.RicoKalkDocumentTransfer.Relay.DocumentTransferRequest request = new  Niedax.AzureServiceBus.Models.RicoKalkDocumentTransfer.Relay.DocumentTransferRequest();
    Niedax.AzureServiceBus.Models.RicoKalkDocumentTransfer.Relay.DocumentTransferResponseContent responseContent  = new Niedax.AzureServiceBus.Models.RicoKalkDocumentTransfer.Relay.DocumentTransferResponseContent();

    str message = '';

    rICOtblAx2Rk_DMS.Aktion = enum2Symbol(enumNum(NDXRICODMSAction), NDXRICODMSAction::Anlage);

    if(docuRef && docuValue)
    {
        System.IO.Stream stream = new System.IO.MemoryStream();
        DocumentManagement::getAttachmentStream(docuRef).CopyTo(stream);

        request.rICOtblAx2Rk_DMS = rICOtblAx2Rk_DMS;
        request.FileContent = stream;

        request.RicoDocumentFolder = lKCS_KBVParameters.NDXRICODMSFolder;
        request.StartFileFolder = lKCS_KBVParameters.NDXRICOProgramStartFolder;

        if(lKCS_KBVParameters.NDXTestEnvironment)
        {
            request.RicoDocumentFolder += Test;
            request.StartFileFolder += Test;
        }

        request.FileCreationAt = docuValue.CreatedDateTime;

        httpResponseMessage = Niedax.AzureRelayHelper.AzureRelayHelperNew::sendRequestToListener(azureRelayParameter, request);

        if(httpResponseMessage.StatusCode == System.Net.HttpStatusCode::OK)
        {
            try
            {
                responseContent =  NDXRicoRelayCommunication::analyzeResponse(httpResponseMessage);
                message = responseContent.Message;
                ret = !responseContent.Error;
            }
            catch(ex)
            {
                message = ex.Message;
            }
        }
        else
        {
            message = strFmt('%1', httpResponseMessage.ReasonPhrase);
        }

        if(ret)
        {
            info(message);
        }
        else
        {
            responseContent.record = rICOtblAx2Rk_DMS;
            warning(message);
        }
    }

    responseContent.Message = message;

    //Log transfer information 
    this.logNDX(NDXRICODMSAction::Anlage, !ret, responseContent);

    return ret;
}

